	ESPGui.Parent = PlayerGui
	local function updateStatus()
		if not Status or not Status.Parent then
			return
		end
		local target =
			ESP_ENABLED
			and ON_COLOR
			or OFF_COLOR
		TweenService:Create(
			Status,
			TweenInfo.new(
				0.15,
				Enum.EasingStyle.Quart,
				Enum.EasingDirection.Out
			),
			{
				BackgroundColor3 = target
			}
		):Play()
	end
	Status.BackgroundColor3 = OFF_COLOR
	local function createPart(parent, name)
		local part = Instance.new(string.char(70,114,97,109,101))
		part.Name = name
		part.BackgroundColor3 = BOX_COLOR
		part.BorderSizePixel = 0
		part.Visible = false
		part.Parent = parent
		return part
	end
	local function createText(parent, name)
		local text = Instance.new(string.char(84,101,120,116,76,97,98,101,108))
		text.Name = name
		text.BackgroundTransparency = 1
		text.BorderSizePixel = 0
