		text.TextStrokeTransparency = 0.15
		text.TextXAlignment = Enum.TextXAlignment.Center
		text.TextYAlignment = Enum.TextYAlignment.Center
		text.Visible = false
		text.Parent = parent
		return text
	end
	local function createESP(player)
