		local healthFill = Instance.new(string.char(70,114,97,109,101))
		healthFill.Name = string.char(72,101,97,108,116,104,70,105,108,108)
		healthFill.BackgroundColor3 = HEALTH_HIGH
		healthFill.BorderSizePixel = 0
		healthFill.AnchorPoint =
