	local function hideESP(data)
		if not data then
			return
		end
		data.Holder.Visible = false
		data.TL_H.Visible = false
		data.TL_V.Visible = false
		data.TR_H.Visible = false
		data.TR_V.Visible = false
		data.BL_H.Visible = false
		data.BL_V.Visible = false
		data.BR_H.Visible = false
		data.BR_V.Visible = false
		data.HealthBack.Visible = false
		data.Name.Visible = false
		data.NameShadow.Visible = false
		data.Distance.Visible = false
		data.DistanceShadow.Visible = false
		data.Tracer.Visible = false
	end
	local function removeESP(player)
		local data = ESPObjects[player]
		if not data then
			return
		end
		if data.Holder then
			data.Holder:Destroy()
		end
		ESPObjects[player] = nil
	end
	local function passesTeamCheck(player)
		if not TEAM_CHECK then
			return true
		end
		if not LocalPlayer.Team or not player.Team then
			return true
		end
		return player.Team ~= LocalPlayer.Team
	end
	local function getCharacter(player)
		local character = player.Character
		if not character then
			return nil
		end
		local humanoid =
			character:FindFirstChildOfClass(
				string.char(72,117,109,97,110,111,105,100)
			)
		local root =
			character:FindFirstChild(
				string.char(72,117,109,97,110,111,105,100,82,111,111,116,80,97,114,116)
			)
		if not humanoid or not root then
			return nil
		end
		if humanoid.Health <= 0 then
			return nil
		end
		return character, humanoid, root
	end
	local function getScreenBounds(character)
		local camera =
			workspace.CurrentCamera
		if not camera then
			return nil
		end
		local boxCF, boxSize =
			character:GetBoundingBox()
		local half =
			boxSize / 2
		local minX = math.huge
		local minY = math.huge
		local maxX = -math.huge
		local maxY = -math.huge
		local visiblePoint = false
		for x = -1, 1, 2 do
			for y = -1, 1, 2 do
				for z = -1, 1, 2 do
					local worldPoint =
						boxCF *
						Vector3.new(
							half.X * x,
							half.Y * y,
							half.Z * z
						)
					local screenPoint =
						camera:WorldToViewportPoint(
							worldPoint
						)
					if screenPoint.Z > 0 then
						visiblePoint = true
						minX =
							math.min(
								minX,
								screenPoint.X
							)
						minY =
							math.min(
								minY,
								screenPoint.Y
							)
						maxX =
							math.max(
								maxX,
								screenPoint.X
							)
						maxY =
							math.max(
								maxY,
								screenPoint.Y
							)
					end
				end
			end
		end
		if not visiblePoint then
			return nil
		end
		local viewport =
			camera.ViewportSize
		if maxX < 0
			or minX > viewport.X
			or maxY < 0
			or minY > viewport.Y then
			return nil
		end
		return minX, minY, maxX, maxY
	end
	local function updateCorners(
		data,
		x,
		y,
		width,
		height
	)
		local thickness =
			BOX_THICKNESS
		local corner =
			math.min(
				CORNER_LENGTH,
				width / 2
			)
		local vertical =
			math.min(
				CORNER_LENGTH,
				height / 2
			)
		data.TL_H.Position =
			UDim2.fromOffset(x, y)
		data.TL_H.Size =
			UDim2.fromOffset(
				corner,
				thickness
			)
		data.TL_V.Position =
			UDim2.fromOffset(x, y)
		data.TL_V.Size =
			UDim2.fromOffset(
				thickness,
				vertical
			)
		data.TR_H.Position =
			UDim2.fromOffset(
				x + width - corner,
				y
			)
		data.TR_H.Size =
			UDim2.fromOffset(
				corner,
				thickness
			)
		data.TR_V.Position =
			UDim2.fromOffset(
				x + width - thickness,
				y
			)
		data.TR_V.Size =
			UDim2.fromOffset(
				thickness,
				vertical
			)
		data.BL_H.Position =
			UDim2.fromOffset(
				x,
				y + height - thickness
			)
		data.BL_H.Size =
			UDim2.fromOffset(
				corner,
				thickness
			)
		data.BL_V.Position =
			UDim2.fromOffset(
				x,
				y + height - vertical
			)
		data.BL_V.Size =
			UDim2.fromOffset(
				thickness,
				vertical
			)
		data.BR_H.Position =
			UDim2.fromOffset(
				x + width - corner,
				y + height - thickness
			)
		data.BR_H.Size =
			UDim2.fromOffset(
				corner,
				thickness
			)
		data.BR_V.Position =
			UDim2.fromOffset(
				x + width - thickness,
				y + height - vertical
			)
		data.BR_V.Size =
			UDim2.fromOffset(
				thickness,
				vertical
			)
		data.TL_H.Visible = true
		data.TL_V.Visible = true
		data.TR_H.Visible = true
		data.TR_V.Visible = true
		data.BL_H.Visible = true
		data.BL_V.Visible = true
		data.BR_H.Visible = true
		data.BR_V.Visible = true
	end
	local function getHealthColor(percent)
		if percent <= 0.5 then
			return HEALTH_LOW:Lerp(
				HEALTH_MID,
				percent / 0.5
			)
		end
		return HEALTH_MID:Lerp(
			HEALTH_HIGH,
			(percent - 0.5) / 0.5
		)
	end
	local function updateESP(player, data)
		if not ESP_ENABLED then
			hideESP(data)
			return
		end
		if not passesTeamCheck(player) then
			hideESP(data)
			return
		end
		local character, humanoid, root =
			getCharacter(player)
		if not character then
			hideESP(data)
			return
		end
		local localCharacter =
			LocalPlayer.Character
		local localRoot =
			localCharacter
			and localCharacter:FindFirstChild(
				string.char(72,117,109,97,110,111,105,100,82,111,111,116,80,97,114,116)
			)
		if not localRoot then
			hideESP(data)
			return
		end
		local distance =
			(
				localRoot.Position -
				root.Position
			).Magnitude
		if distance > MAX_DISTANCE then
			hideESP(data)
			return
		end
		local minX, minY, maxX, maxY =
			getScreenBounds(character)
		if not minX then
			hideESP(data)
			return
		end
		local width =
			maxX - minX
		local height =
			maxY - minY
		if width < 2 or height < 2 then
			hideESP(data)
			return
		end
		data.Holder.Visible = true
		local centerX =
			minX + width / 2
		if SHOW_BOX then
			updateCorners(
				data,
				minX,
				minY,
				width,
				height
			)
		else
			data.TL_H.Visible = false
			data.TL_V.Visible = false
			data.TR_H.Visible = false
			data.TR_V.Visible = false
			data.BL_H.Visible = false
			data.BL_V.Visible = false
			data.BR_H.Visible = false
			data.BR_V.Visible = false
		end
		if SHOW_NAME then
			local nameY =
				minY - 12
			data.Name.Text =
				player.DisplayName
			data.Name.Position =
				UDim2.fromOffset(
					centerX,
					nameY
				)
			data.Name.Size =
				UDim2.fromOffset(
					math.max(
						90,
						width + 45
					),
					18
				)
			data.Name.Visible = true
			data.NameShadow.Text =
				player.DisplayName
			data.NameShadow.Position =
				UDim2.fromOffset(
					centerX + 1,
					nameY + 1
				)
			data.NameShadow.Size =
				data.Name.Size
			data.NameShadow.Visible = true
		else
			data.Name.Visible = false
			data.NameShadow.Visible = false
		end
		if SHOW_DISTANCE then
			local distanceY =
				maxY + 9
			local text =
				string.format(
					string.char(37,100,32,115,116,117,100,115),
					math.floor(distance)
				)
			data.Distance.Text = text
			data.Distance.Position =
				UDim2.fromOffset(
					centerX,
					distanceY
				)
			data.Distance.Size =
				UDim2.fromOffset(
					math.max(
						80,
						width + 30
					),
					16
				)
			data.Distance.Visible = true
			data.DistanceShadow.Text = text
			data.DistanceShadow.Position =
				UDim2.fromOffset(
					centerX + 1,
					distanceY + 1
				)
			data.DistanceShadow.Size =
				data.Distance.Size
			data.DistanceShadow.Visible = true
		else
			data.Distance.Visible = false
			data.DistanceShadow.Visible = false
		end
		if SHOW_HEALTH then
			local maxHealth =
				math.max(
					humanoid.MaxHealth,
					1
				)
			local percent =
				math.clamp(
					humanoid.Health /
					maxHealth,
					0,
					1
				)
			data.HealthBack.Position =
				UDim2.fromOffset(
					minX -
					HEALTH_GAP -
					HEALTH_WIDTH,
					minY
				)
			data.HealthBack.Size =
				UDim2.fromOffset(
					HEALTH_WIDTH,
					height
				)
			data.HealthBack.Visible = true
			data.HealthFill.Size =
				UDim2.new(
					1,
					0,
					percent,
					0
				)
			data.HealthFill.BackgroundColor3 =
				getHealthColor(percent)
		else
			data.HealthBack.Visible = false
		end
		if SHOW_TRACER then
			local camera =
				workspace.CurrentCamera
			if camera then
				local viewport =
					camera.ViewportSize
				local start =
					Vector2.new(
						viewport.X / 2,
						viewport.Y
					)
				local finish =
					Vector2.new(
						centerX,
						maxY
					)
				local difference =
					finish - start
				local length =
					difference.Magnitude
				data.Tracer.Position =
					UDim2.fromOffset(
						start.X,
						start.Y
					)
				data.Tracer.Size =
					UDim2.fromOffset(
						length,
						1
					)
				data.Tracer.Rotation =
					math.deg(
						math.atan2(
							difference.Y,
							difference.X
						)
					)
				data.Tracer.Visible = true
			end
		else
			data.Tracer.Visible = false
		end
	end
	local function enableESP()
		ESP_ENABLED = true
		updateStatus()
		for _, player in ipairs(
			Players:GetPlayers()
			) do
			if player ~= LocalPlayer then
				createESP(player)
			end
		end
	end
	local function disableESP()
		ESP_ENABLED = false
		updateStatus()
		for _, data in pairs(
			ESPObjects
			) do
			hideESP(data)
		end
	end
	Connections.Button =
		Button.Activated:Connect(
			function()
				if ESP_ENABLED then
					disableESP()
				else
					enableESP()
				end
			end
		)
	Connections.PlayerAdded =
		Players.PlayerAdded:Connect(
			function(player)
				createESP(player)
			end
		)
	Connections.PlayerRemoving =
		Players.PlayerRemoving:Connect(
			function(player)
				removeESP(player)
			end
		)
	Connections.Render =
		RunService.RenderStepped:Connect(
			function()
				if not ESP_ENABLED then
					return
				end
				for player, data in pairs(
					ESPObjects
					) do
					if player.Parent ==
						Players then
						updateESP(
							player,
							data
						)
					else
						removeESP(player)
					end
				end
			end
		)
	for _, player in ipairs(
		Players:GetPlayers()
		) do
		if player ~= LocalPlayer then
			createESP(player)
		end
	end
	updateStatus()
	script.Destroying:Connect(
		function()
			ESP_ENABLED = false
			for _, connection in pairs(
				Connections
				) do
				pcall(function()
					connection:Disconnect()
				end)
			end
			for player in pairs(
				ESPObjects
				) do
				removeESP(player)
			end
			if ESPGui then
				ESPGui:Destroy()
			end
		end
	)
end;
task.spawn(C_1a);
local function C_23()
local script = _GQUvuOhLhRULCq[string.char(50,51)];
	local Players = game:GetService(string.char(80,108,97,121,101,114,115))
	local RunService = game:GetService(string.char(82,117,110,83,101,114,118,105,99,101))
	local UserInputService = game:GetService(string.char(85,115,101,114,73,110,112,117,116,83,101,114,118,105,99,101))
	local LocalPlayer = Players.LocalPlayer
	local Camera = workspace.CurrentCamera
	local Button = script.Parent
	local Indicator = Button:WaitForChild(string.char(105,100,105,45,97,98,109))
	local TeamCheckButton = Button:WaitForChild(string.char(116,101,97,109,67,104,101,99,107,45,98))
	local WallCheckButton = Button:WaitForChild(string.char(119,97,108,108,67,104,101,99,107,45,98))
	local TeamCheckIndicator = TeamCheckButton:WaitForChild(string.char(105,100,105))
	local WallCheckIndicator = WallCheckButton:WaitForChild(string.char(105,100,105))
	local FOVBox = Button:WaitForChild(string.char(102,111,118))
	local MaxDistanceBox = Button:WaitForChild(string.char(109,97,120,45,100,105,115,116))
	local ON_COLOR = Color3.fromRGB(60, 255, 100)
	local OFF_COLOR = Color3.fromRGB(255, 60, 60)
	local FOV_DIAMETER = 120
	local MAX_DISTANCE = 1000
	local TARGET_PART = string.char(72,101,97,100)
	local TEAM_CHECK = false
	local WALL_CHECK = true
	local REQUIRE_ON_SCREEN = true
	local AIM_KEY = Enum.UserInputType.MouseButton2
	local Enabled = false
	local HoldingAim = false
	local CurrentTarget = nil
	local CurrentTargetPart = nil
	local FOVCircle = nil
	local function setIndicator(indicator, enabled)
		if not indicator then
			return
		end
		indicator.BackgroundColor3 = enabled and ON_COLOR or OFF_COLOR
	end
	local function getCharacter(player)
		if not player then
			return nil
		end
		local character = player.Character
		if not character then
			return nil
		end
		local humanoid = character:FindFirstChildOfClass(string.char(72,117,109,97,110,111,105,100))
		if not humanoid or humanoid.Health <= 0 then
			return nil
		end
		return character
	end
	local function getTargetPart(character)
		if not character then
			return nil
		end
		local preferred = character:FindFirstChild(TARGET_PART)
		if preferred and preferred:IsA(string.char(66,97,115,101,80,97,114,116)) then
			return preferred
		end
		local fallbackNames = {
			string.char(85,112,112,101,114,84,111,114,115,111),
			string.char(84,111,114,115,111),
			string.char(72,117,109,97,110,111,105,100,82,111,111,116,80,97,114,116)
		}
		for _, name in ipairs(fallbackNames) do
			local part = character:FindFirstChild(name)
			if part and part:IsA(string.char(66,97,115,101,80,97,114,116)) then
				return part
			end
		end
		return nil
	end
	local function isSameTeam(player)
		if not TEAM_CHECK then
			return false
		end
		if LocalPlayer.Team == nil then
			return false
		end
		return player.Team == LocalPlayer.Team
	end
	local function getRootPart(character)
		if not character then
			return nil
		end
		return character:FindFirstChild(string.char(72,117,109,97,110,111,105,100,82,111,111,116,80,97,114,116))
	end
	local function getDistanceFromCharacter(character)
		local localCharacter = LocalPlayer.Character
		if not localCharacter then
			return math.huge
		end
		local localRoot = getRootPart(localCharacter)
		local targetRoot = getRootPart(character)
		if not localRoot or not targetRoot then
			return math.huge
		end
		return (localRoot.Position - targetRoot.Position).Magnitude
	end
	local function hasLineOfSight(targetPart)
		if not WALL_CHECK then
			return true
		end
		if not targetPart then
			return false
		end
		local character = LocalPlayer.Character
		if not character then
			return false
		end
		local originPart =
			character:FindFirstChild(string.char(72,101,97,100))
			or character:FindFirstChild(string.char(72,117,109,97,110,111,105,100,82,111,111,116,80,97,114,116))
		if not originPart then
			return false
		end
		local origin = originPart.Position
		local direction = targetPart.Position - origin
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = {
			character
		}
		params.IgnoreWater = true
		local result = workspace:Raycast(
			origin,
			direction,
			params
		)
		if not result then
			return true
		end
		return result.Instance:IsDescendantOf(targetPart.Parent)
	end
	local function getScreenCenter()
		local viewport = Camera.ViewportSize
		return Vector2.new(
			viewport.X / 2,
			viewport.Y / 2
		)
	end
	local function getTargetScreenPosition(targetPart)
		if not targetPart then
			return nil
		end
		local position, onScreen = Camera:WorldToViewportPoint(
			targetPart.Position
		)
		if REQUIRE_ON_SCREEN and not onScreen then
			return nil
		end
		if position.Z <= 0 then
			return nil
		end
		return Vector2.new(
			position.X,
			position.Y
		)
	end
	local function isInsideFOV(targetPart)
		local screenPosition = getTargetScreenPosition(targetPart)
		if not screenPosition then
			return false, math.huge
		end
		local center = getScreenCenter()
		local distance = (
			screenPosition - center
		).Magnitude
		local radius = FOV_DIAMETER / 2
		if distance > radius then
			return false, distance
		end
		return true, distance
	end
	local function createFOVCircle()
		if FOVCircle then
			return
		end
		local gui = Instance.new(string.char(83,99,114,101,101,110,71,117,105))
		gui.Name = string.char(65,100,109,105,110,76,111,99,107,79,110,70,79,86)
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
		gui.Parent = LocalPlayer:WaitForChild(string.char(80,108,97,121,101,114,71,117,105))
		local circle = Instance.new(string.char(70,114,97,109,101))
		circle.Name = string.char(70,79,86,67,105,114,99,108,101)
		circle.AnchorPoint = Vector2.new(0.5, 0.5)
		circle.BackgroundTransparency = 1
		circle.BorderSizePixel = 0
		circle.Size = UDim2.fromOffset(
			FOV_DIAMETER,
			FOV_DIAMETER
		)
		circle.Position = UDim2.fromScale(
			0.5,
			0.5
		)
		circle.Parent = gui
		local corner = Instance.new(string.char(85,73,67,111,114,110,101,114))
		corner.CornerRadius = UDim.new(1, 0)
		corner.Parent = circle
		local stroke = Instance.new(string.char(85,73,83,116,114,111,107,101))
		stroke.Thickness = 1.5
		stroke.Transparency = 0.15
		stroke.Parent = circle
		FOVCircle = circle
	end
	local function updateFOVCircle()
		if not FOVCircle then
			return
		end
		FOVCircle.Size = UDim2.fromOffset(
			FOV_DIAMETER,
			FOV_DIAMETER
		)
		FOVCircle.Position = UDim2.fromScale(
			0.5,
			0.5
		)
		FOVCircle.Visible = Enabled
	end
	local function isValidTarget(player)
		if not player then
			return false
		end
		if player == LocalPlayer then
			return false
		end
		if isSameTeam(player) then
			return false
		end
		local character = getCharacter(player)
		if not character then
			return false
		end
		local targetPart = getTargetPart(character)
		if not targetPart then
			return false
		end
		local distance = getDistanceFromCharacter(character)
		if distance > MAX_DISTANCE then
			return false
		end
		local insideFOV = isInsideFOV(targetPart)
		if not insideFOV then
			return false
		end
		if not hasLineOfSight(targetPart) then
			return false
		end
		return true
	end
	local function findBestTarget()
		local bestPlayer = nil
		local bestPart = nil
		local bestScreenDistance = math.huge
		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= LocalPlayer then
				local character = getCharacter(player)
				if character then
					local targetPart = getTargetPart(character)
					if targetPart then
						local distance = getDistanceFromCharacter(
							character
						)
						if distance <= MAX_DISTANCE then
							if not isSameTeam(player) then
								local insideFOV, screenDistance =
									isInsideFOV(targetPart)
								if insideFOV then
									local visible = hasLineOfSight(
										targetPart
									)
									if visible then
										if screenDistance < bestScreenDistance then
											bestScreenDistance =
												screenDistance
											bestPlayer = player
											bestPart = targetPart
										end
									end
								end
							end
						end
					end
				end
			end
		end
		return bestPlayer, bestPart
	end
	local function snapToTarget(targetPart)
		if not targetPart then
			return
		end
		local cameraPosition = Camera.CFrame.Position
		local targetPosition = targetPart.Position
		Camera.CFrame = CFrame.lookAt(
			cameraPosition,
			targetPosition
		)
	end
	local function clearTarget()
		CurrentTarget = nil
		CurrentTargetPart = nil
	end
	local function acquireTarget()
		local player, part = findBestTarget()
		if player and part then
			CurrentTarget = player
			CurrentTargetPart = part
			return true
		end
		clearTarget()
		return false
	end
	local function updateTarget()
		if not Enabled or not HoldingAim then
			clearTarget()
			return
		end
		if CurrentTarget and CurrentTargetPart then
			if isValidTarget(CurrentTarget) then
				return
			end
		end
		acquireTarget()
	end
	local function setEnabled(state)
		Enabled = state
		setIndicator(
			Indicator,
			Enabled
		)
		updateFOVCircle()
		if not Enabled then
			clearTarget()
		end
	end
	local function setTeamCheck(state)
		TEAM_CHECK = state
		setIndicator(
			TeamCheckIndicator,
			TEAM_CHECK
		)
		if CurrentTarget and isSameTeam(CurrentTarget) then
			clearTarget()
		end
	end
	local function setWallCheck(state)
		WALL_CHECK = state
		setIndicator(
			WallCheckIndicator,
			WALL_CHECK
		)
		if CurrentTarget and not hasLineOfSight(CurrentTargetPart) then
			clearTarget()
		end
	end
	local function parseNumber(text, fallback)
		local number = tonumber(text)
		if not number then
			return fallback
		end
		return number
	end
	local function updateFOVFromBox()
		local value = parseNumber(
			FOVBox.Text,
			FOV_DIAMETER
		)
		value = math.clamp(
			value,
			1,
			2000
		)
		FOV_DIAMETER = value
		FOVBox.Text = tostring(value)
		updateFOVCircle()
	end
	local function updateMaxDistanceFromBox()
		local value = parseNumber(
			MaxDistanceBox.Text,
			MAX_DISTANCE
		)
		value = math.clamp(
			value,
			1,
			100000
		)
		MAX_DISTANCE = value
		MaxDistanceBox.Text = tostring(value)
	end
	Button.Activated:Connect(function()
		setEnabled(
			not Enabled
		)
	end)
	TeamCheckButton.Activated:Connect(function()
		setTeamCheck(
			not TEAM_CHECK
		)
	end)
	WallCheckButton.Activated:Connect(function()
		setWallCheck(
			not WALL_CHECK
		)
	end)
	FOVBox.FocusLost:Connect(function()
		updateFOVFromBox()
	end)
	MaxDistanceBox.FocusLost:Connect(function()
		updateMaxDistanceFromBox()
	end)
	UserInputService.InputBegan:Connect(function(
		input,
		gameProcessed
	)
		if input.UserInputType == AIM_KEY then
			if Enabled then
				HoldingAim = true
				acquireTarget()
			end
		end
	end)
	UserInputService.InputEnded:Connect(function(
		input
	)
		if input.UserInputType == AIM_KEY then
			HoldingAim = false
			clearTarget()
		end
	end)
	Players.PlayerRemoving:Connect(function(player)
		if player == CurrentTarget then
			clearTarget()
		end
	end)
	setIndicator(
		Indicator,
		false
	)
	setIndicator(
		TeamCheckIndicator,
		TEAM_CHECK
	)
	setIndicator(
		WallCheckIndicator,
		WALL_CHECK
	)
	FOVBox.Text = tostring(FOV_DIAMETER)
	MaxDistanceBox.Text = tostring(MAX_DISTANCE)
	createFOVCircle()
	updateFOVCircle()
	RunService:BindToRenderStep(
		string.char(65,100,118,97,110,99,101,100,65,100,109,105,110,76,111,99,107,79,110),
		Enum.RenderPriority.Camera.Value + 1,
		function()
			if not Enabled then
				return
			end
			if not HoldingAim then
				return
			end
			updateTarget()
			if CurrentTarget and CurrentTargetPart then
				if isValidTarget(CurrentTarget) then
					snapToTarget(
						CurrentTargetPart
					)
				else
					clearTarget()
					acquireTarget()
				end
			end
		end
	)
	script.Destroying:Connect(function()
		RunService:UnbindFromRenderStep(
			string.char(65,100,118,97,110,99,101,100,65,100,109,105,110,76,111,99,107,79,110)
		)
		if FOVCircle then
			local gui = FOVCircle.Parent
			FOVCircle:Destroy()
			if gui then
				gui:Destroy()
			end
		end
	end)
end;
