local function C_38()
local script = _GQUvuOhLhRULCq[string.char(51,56)];
	local Players = game:GetService(string.char(80,108,97,121,101,114,115))
	local RunService = game:GetService(string.char(82,117,110,83,101,114,118,105,99,101))
	local TweenService = game:GetService(string.char(84,119,101,101,110,83,101,114,118,105,99,101))
	local player = Players.LocalPlayer
	local button = script.Parent
	local indicator = button:WaitForChild(string.char(105,100,105,45,115,98,116))
	local speedBox = button.Parent:WaitForChild(string.char(115,112,105,110,45,115,112,101,101,100))
	local SPIN_SPEED = 1800
	local function updateSpeed()
		local text = speedBox.Text
		local number = tonumber(text)
		if number then
			SPIN_SPEED = math.max(0, number)
		end
	end
	speedBox.FocusLost:Connect(function()
		updateSpeed()
	end)
	updateSpeed()
	local spinning = false
	local OFF_COLOR = Color3.fromRGB(255, 60, 60)
	local ON_COLOR = Color3.fromRGB(70, 220, 100)
	local function updateIndicator()
		local targetColor
		if spinning then
			targetColor = ON_COLOR
		else
			targetColor = OFF_COLOR
		end
		TweenService:Create(
			indicator,
			TweenInfo.new(
				0.15,
				Enum.EasingStyle.Quart,
				Enum.EasingDirection.Out
			),
			{
				BackgroundColor3 = targetColor
			}
		):Play()
	end
	indicator.BackgroundColor3 = OFF_COLOR
	local function releaseCharacter()
		local character = player.Character
		if not character then
			return
		end
		local humanoid =
			character:FindFirstChildOfClass(string.char(72,117,109,97,110,111,105,100))
		local root =
			character:FindFirstChild(string.char(72,117,109,97,110,111,105,100,82,111,111,116,80,97,114,116))
		if humanoid then
			humanoid.AutoRotate = true
			if humanoid.Health > 0 then
				humanoid:ChangeState(
					Enum.HumanoidStateType.Running
				)
			end
		end
		if root then
			root.AssemblyAngularVelocity =
				Vector3.zero
		end
	end
	button.Activated:Connect(function()
		spinning = not spinning
		if spinning then
			local character = player.Character
			if character then
				local humanoid =
					character:FindFirstChildOfClass(
						string.char(72,117,109,97,110,111,105,100)
					)
				if humanoid then
					humanoid.AutoRotate = false
				end
			end
		else
			releaseCharacter()
		end
